  const mode = OP_MODE[op];
  const domain = OP_DOMAIN[op];
  return Object.freeze({ op, grain, mode, domain, terrain: TERRAIN_BY_DOMAIN[domain][grain], stance: STANCE_BY_MODE[mode][grain] });
};
