:root{--bg:#f6f5f1;--card:#ffffff;--ink:#1c1c21;--ink2:#53535d;--line:#8d8b84;--hair:#dedcd3;--stand:#0b6a4d;--stand-bg:#dff0e8;--differ:#8a4a00;--differ-bg:#fbebd3;--nul:#3a4c96;--nul-bg:#e4e8f8;--focus:#1a56db;--sans:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;--serif:Georgia,"Times New Roman",serif;color-scheme:light}
/*TOKENS_DARK_AUTO*/
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#131417;--card:#1c1d22;--ink:#ececf0;--ink2:#b6b6c0;--line:#8a8a94;--hair:#34353d;--stand:#62d3a8;--stand-bg:#163428;--differ:#f2b563;--differ-bg:#3b2a11;--nul:#a5b5ff;--nul-bg:#232b4a;--focus:#8db0ff;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#131417;--card:#1c1d22;--ink:#ececf0;--ink2:#b6b6c0;--line:#8a8a94;--hair:#34353d;--stand:#62d3a8;--stand-bg:#163428;--differ:#f2b563;--differ-bg:#3b2a11;--nul:#a5b5ff;--nul-bg:#232b4a;--focus:#8db0ff;color-scheme:dark}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 var(--sans)}
button,select{font:inherit;color:inherit}
a{color:inherit}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px;border-radius:3px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

/* the mock's own bar (not part of the component) */
.mock{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center;padding:8px 16px;border-bottom:1px solid var(--hair);font-size:12px;color:var(--ink2)}
.mock select,.mock button{background:var(--card);border:1px solid var(--line);border-radius:6px;padding:3px 8px;min-height:28px;cursor:pointer}
.mock .sp{flex:1}

.wrap{max-width:1160px;margin:0 auto;padding:0 16px 64px}
.top{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0 6px;position:relative}
.crumbs ol{display:flex;flex-wrap:wrap;gap:2px 6px;list-style:none;margin:0;padding:0;font-size:13px;color:var(--ink2)}
.crumbs li+li::before{content:"\203A";margin-right:6px}
.crumbs [aria-current]{color:var(--ink);font-weight:600}
.jump{position:relative}
.jump>summary{list-style:none;cursor:pointer;font-size:13px;color:var(--ink2);padding:4px 8px;border:1px solid var(--line);border-radius:6px;background:var(--card);min-height:30px;display:flex;align-items:center;gap:6px}
.jump>summary::-webkit-details-marker{display:none}
.jump[open]>summary{color:var(--ink)}
.jump .pan{position:absolute;right:0;top:36px;z-index:20;width:min(420px,calc(100vw - 32px));background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px;box-shadow:0 8px 24px rgba(0,0,0,.18)}
.jump table{width:100%;border-collapse:collapse;font-size:13px}
.jump th{font-weight:600;text-align:left;padding:2px 4px;color:var(--ink2);font-size:12px;vertical-align:bottom}
.jump th small{display:block;font-weight:400}
.jump td{padding:3px}
.jump td a{display:block;padding:7px 8px;border:1px solid var(--hair);border-radius:6px;text-decoration:none;min-height:36px}
.jump td a[aria-current]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.jump p{margin:8px 0 0;font-size:12px;color:var(--ink2)}

.tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-bottom:1px solid var(--line)}
.tab{background:none;border:0;border-bottom:3px solid transparent;margin-bottom:-1px;padding:8px 6px 7px;text-align:left;color:var(--ink2);cursor:pointer;min-height:48px}
.tab b{display:block;font-size:15px;font-weight:600}
.tab small{display:block;font-size:12px;line-height:1.25}
.tab[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--ink)}
.caption{margin:14px 0 4px;font-size:15px;max-width:70ch}
.sub{margin:0 0 12px;font-size:13px;color:var(--ink2);max-width:70ch}

.layout{display:grid;grid-template-columns:minmax(0,1fr);gap:20px;margin-top:10px}
