.nul .meta { font-size: 13px; color: var(--mut); margin-bottom: 16px; max-width: 70ch; }
/* the slot: a blank the shape of the answer */
.slot { border-radius: var(--r-md); padding: 14px 16px; display: grid; gap: 6px; align-content: center; min-height: 128px; max-width: 760px; }
.slot.open { border: 2px dashed var(--line2); background: repeating-linear-gradient(135deg, transparent 0 9px, color-mix(in srgb, var(--line) 55%, transparent) 9px 10px); }
.slot.full { border: 2px solid var(--ag); background: var(--bg); }
.slot .said { font-size: 16.5px; line-height: 1.5; color: var(--ink); }
.slot .said2 { font-size: 16px; color: var(--ink2); max-width: 46ch; }
.slot .who { display: flex; gap: 8px; align-items: center; font-size: 13px; color: var(--ink2); flex-wrap: wrap; }
.slot .stand { font-size: 12px; color: var(--mut); }
.slot:not(.mini) .stand:not(.mono) { font-size: 13.5px; color: var(--ink2); }
.cursor { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0; margin: 16px 0 0; max-width: 760px; border-top: 1px solid var(--line); }
.cursor > div { padding: 10px 0 0; }
