.cells{display:inline-flex;gap:3px;min-width:34px}
.lp .dl{font-size:12.5px;font-weight:600}
.lp .ar{color:var(--ink2)}
@media (max-width:560px){
  .lp,.lp-h{grid-template-columns:minmax(0,1fr) auto 14px auto;gap:6px}
  .lp .dl{grid-column:1 / -1;font-size:12px;color:var(--ink2);font-weight:600;padding-left:2px}
  .lp-h span:last-child{display:none}
  .lp-h span:nth-child(2),.lp-h span:nth-child(4){font-size:11px}
}
