.lps>li{border-bottom:1px solid var(--hair)}
.lp,.lp-h{display:grid;grid-template-columns:minmax(0,1fr) auto 18px auto 92px;gap:10px;align-items:center}
.lp-h{font-size:12px;color:var(--ink2);padding:0 4px 4px;border-bottom:1px solid var(--line)}
.lp-h span:nth-child(2){grid-column:2}
.lp-h span:nth-child(4){grid-column:4}
.lp{width:100%;background:none;border:0;padding:9px 4px;cursor:pointer;text-align:left;color:inherit;min-height:48px}
.lp[aria-pressed="true"]{background:var(--card);box-shadow:inset 3px 0 0 var(--ink)}
.lp .lbl{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.lp .lbl small{display:block;font-size:12px;color:var(--ink2)}
.cells{display:inline-flex;gap:3px;min-width:34px}
.lp .dl{font-size:12.5px;font-weight:600}
.lp .ar{color:var(--ink2)}
@media (max-width:560px){
  .lp,.lp-h{grid-template-columns:minmax(0,1fr) auto 14px auto;gap:6px}
  .lp .dl{grid-column:1 / -1;font-size:12px;color:var(--ink2);font-weight:600;padding-left:2px}
  .lp-h span:last-child{display:none}
  .lp-h span:nth-child(2),.lp-h span:nth-child(4){font-size:11px}
}
