export function loadStore() { try { return JSON.parse(fs.readFileSync(STORE_FILE, "utf8")); } catch { return {}; } }
export function saveStore(store) { fs.mkdirSync(path.dirname(STORE_FILE), { recursive: true }); fs.writeFileSync(STORE_FILE + ".tmp", JSON.stringify(store)); fs.renameSync(STORE_FILE + ".tmp", STORE_FILE); }
