export async function door(text) {
  const key = crypto.createHash("sha1").update(text).digest("hex"); const f = path.join(DIR, key + ".json");
  if (fs.existsSync(f)) { STATS.doorHit++; return JSON.parse(fs.readFileSync(f, "utf8")); }
