  t0 = Date.now();
  const quickWeb = await searchWeb("Eiffel Tower height", { fetchImpl: mk(900), effort: "fast", route: false, scopes: ["web", "wikipedia"] });
  assert.ok(quickWeb.results.some((r) => r.kind === "web"), "a web that answers inside the grace is still used");
});
